    // Mock repository
    type mockRepo struct{ items map[int64]Item }
    func (m mockRepo) Load(id int64) Item { return m.items[id] }
    func (m mockRepo) LoadMany(ids []int64) []Item { var res []Item; for _, id := range ids { res = append(res, m.Load(id)) }; return res }

