import { enrich } from './enrichment';
import { Repository } from './repository';

describe('enrich', () => {
  const mockRepo = {
    load: jest.fn()
  } as unknown as Repository;

  it('returns only active items with enabled owners', async () => {
    mockRepo.load.mockResolvedValueOnce({
      active: true,
      owner: { enabled: true }
    });
    mockRepo.load.mockResolvedValueOnce({
      active: true,
      owner: { enabled: false }
    });
    mockRepo.load.mockResolvedValueOnce({
      active: false,
      owner: { enabled: true }
    });
    const result = await enrich(['1', '2', '3'], mockRepo);
    expect(result).toEqual([
      { active: true, owner: { enabled: true } }
    ]);
  });
});

